<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElButton, ElCheckbox, ElCheckboxGroup, ElDialog, ElDropdown, ElDropdownItem, ElDropdownMenu, ElInput, ElInputNumber, ElMessage, ElMessageBox, ElOption, ElSelect, ElTag } from 'element-plus'
import { ArrowUpToLine, ChevronDown, ClipboardList, Coins, Eye, LayoutGrid, List, TableProperties, MoreHorizontal, Package, PackageCheck, Pencil, Plus, Search } from 'lucide-vue-next'
import { useProductsStore, salePrice, defaultSupply, validSupplyPrice, type Product, type Supply } from '@/stores/products'
import { useCommerceStore } from '@/stores/commerce'
import { useOnboardingStore } from '@/stores/onboarding'
import DemoImage from '@/components/commerce/DemoImage.vue'
import DemoMedia from '@/components/commerce/DemoMedia.vue'
import ProductPriceHistoryChart from './ProductPriceHistoryChart.vue'
import ProductAdjustmentHistory from './ProductAdjustmentHistory.vue'
import SupplyFields from './SupplyFields.vue'
import { submitApprovals, finishApprovals } from './productApprovals'
import { safeProductHtml } from './productRichHtml'
import ListPagination from '@/components/commerce/ListPagination.vue'
import SecondaryPageHeader from '@/components/commerce/SecondaryPageHeader.vue'
import ListStatusTabs from '@/components/commerce/ListStatusTabs.vue'
import ListFilterBar from '@/components/commerce/ListFilterBar.vue'
import ParkListingStatuses from '@/components/commerce/ParkListingStatuses.vue'
const store=useProductsStore(), c=useCommerceStore(), ob=useOnboardingStore(), router=useRouter(), route=useRoute()
type ListState = {name:string;code:string;park:string;query:{name:string;code:string;park:string};tab:string;viewMode:'list'|'grid'|'table';page:number;scrollTop:number}
function listStateKey() { return `product-list-return-state-${ob.activeId}` }
function savedListState():Partial<ListState> { try { return JSON.parse(sessionStorage.getItem(listStateKey())||'{}') } catch { return {} } }
const saved=route.name==='product' ? savedListState() : {}
const name=ref(saved.name||''),code=ref(saved.code||''),park=ref(saved.park||''),query=ref(saved.query||{name:'',code:'',park:''}),tab=ref(saved.tab||'all'),viewMode=ref<'list'|'grid'|'table'>(saved.viewMode||'list'),expandedProduct=ref<string|null>(null),page=ref(saved.page||1)
onMounted(async()=>{if(route.name!=='product'||route.query.restoreList!=='1'||typeof saved.scrollTop!=='number')return;await nextTick();requestAnimationFrame(()=>{const main=document.querySelector<HTMLElement>('.shell-main');if(main){const behavior=main.style.scrollBehavior;main.style.scrollBehavior='auto';main.scrollTop=saved.scrollTop!;main.style.scrollBehavior=behavior}})})
const historyPark=ref(''),historyMode=ref<'taxed'|'untaxed'>('taxed'),historyExample=ref(false)
watch(historyPark,()=>{historyExample.value=false},{flush:'sync'})
const parkOpen=ref(false), parkTargets=ref<string[]>([]), parkAction=ref<'on_sale'|'offline'>('on_sale'); const priceTargets=ref<string[]>([]); const stockOpen=ref(false),priceOpen=ref(false),historyOpen=ref(false),target=ref<Product|null>(null),priceDefaults=reactive<Supply>(defaultSupply()),priceDrafts=reactive<Record<string,Supply>>({}),priceFields=ref<string[]>([]),priceNote=ref('')
const stockOwner=ref(''),stockIds=ref<string[]>([]),stockSelected=ref<string[]>([]),stockBatch=ref<number|undefined>(),stockOriginal=reactive<Record<string,number>>({}),stockDraft=reactive<Record<string,number|undefined>>({})
const changedStockIds=computed(()=>stockIds.value.filter(id=>stockDraft[id]!==stockOriginal[id]))
const priceHistoryPark=ref(''),priceExpandedPark=ref(''),priceOwner=ref('')
const priceFieldsRenderKey=ref(0)
const priceFormRef=ref<HTMLElement|null>(null)
let priceFormScroll=0
async function showPriceHistory(id:string){if(document.activeElement instanceof HTMLElement)document.activeElement.blur();await nextTick();const body=priceFormRef.value?.closest<HTMLElement>('.el-dialog__body');priceFormScroll=body?.scrollTop||0;priceHistoryPark.value=id;await nextTick();if(body)body.scrollTop=0}
async function returnToPrice(){priceFieldsRenderKey.value++;priceHistoryPark.value='';await nextTick();const body=priceFormRef.value?.closest<HTMLElement>('.el-dialog__body');if(body)body.scrollTop=priceFormScroll}
function initialiseStock(p:Product){stockOwner.value=ob.activeId;stockIds.value=c.joinedParks.filter(park=>eligiblePark(p,park.id,'offline')).map(park=>park.id);stockSelected.value=[];stockBatch.value=undefined;for(const key of Object.keys(stockOriginal))delete stockOriginal[key];for(const key of Object.keys(stockDraft))delete stockDraft[key];for(const id of stockIds.value){stockOriginal[id]=p.parks[id].stock;stockDraft[id]=p.parks[id].stock}}
function selectStockPark(id:string,value:string|number|boolean){stockSelected.value=value?[...new Set([...stockSelected.value,id])]:stockSelected.value.filter(item=>item!==id)}
function applyStockBatch(){if(!stockSelected.value.length){ElMessage.warning('请选择需要统一设置的园区');return}if(!Number.isSafeInteger(stockBatch.value)||Number(stockBatch.value)<0){ElMessage.warning('请输入大于或等于 0 的整数库存');return}for(const id of stockSelected.value)if(stockIds.value.includes(id))stockDraft[id]=stockBatch.value;ElMessage.success('已填入所选园区，请确认后保存')}
const currentProduct=computed(()=>store.products.find(p=>p.id===route.params.id))
const detailTab=ref<'basic'|'supply'|'description'>('basic'),detailPark=ref(''),detailMedia=ref('')
watch(()=>route.params.id,()=>{detailTab.value='basic';detailPark.value=currentProduct.value?.parkIds[0]||'';detailMedia.value=currentProduct.value?.cover||''},{immediate:true})
function saveListState() { try { sessionStorage.setItem(listStateKey(),JSON.stringify({name:name.value,code:code.value,park:park.value,query:query.value,tab:tab.value,viewMode:viewMode.value,page:page.value,scrollTop:document.querySelector<HTMLElement>('.shell-main')?.scrollTop||0})) } catch { /* unavailable session storage must not block navigation */ } }
function showDetail(p:Product) { saveListState();router.push({name:'product-detail',params:{id:p.id}}) }
async function copySku(value:string) { try { await navigator.clipboard.writeText(value); ElMessage.success('订货编码已复制') } catch { ElMessage.warning('复制失败，请手动选择编码') } }
function historyTaxPrice(price:number,tax?:number) { return typeof tax==='number' && Number.isFinite(tax) ? `¥${(price*(1+tax/100)).toFixed(2)}` : '—' }
function backFromDetail() { const order=typeof route.query.fromOrder==='string'?route.query.fromOrder:'';const returnPath=typeof route.query.orderReturn==='string'?route.query.orderReturn:'';router.push(order ? (returnPath.startsWith('/procurement/orders?')?returnPath:{path:'/procurement/orders',query:{order}}) : '/product') }
const exampleHistory=[{time:'2026/08/31 17:22:32',original:120,sale:100,tax:13},{time:'2026/09/20 17:22:32',original:110,sale:95,tax:13},{time:'2026/10/23 17:22:32',original:100,sale:90,tax:13}]
const historyRows=computed(()=>historyExample.value ? [...exampleHistory].reverse().map(h=>({...h,parkId:historyPark.value})) : [...(target.value?.priceHistory||[])].filter(h=>!historyPark.value||h.parkId===historyPark.value).reverse())
function showHistoryExample() { if(!historyPark.value && target.value) historyPark.value=historyParkIds(target.value)[0]||'';historyExample.value=true }
function historyParkIds(p:Product) { return [...new Set([...p.parkIds,...(p.priceHistory||[]).map(h=>h.parkId)])] }
function margin(price:number,cost:number) { return price>0 ? `${((price-cost)/price*100).toFixed(2)}%` : '—' }
const labels:Record<Product['status'],string>={draft:'草稿',reviewing:'上架审核中',rejected:'审核驳回',on_sale:'已上架',offline:'已下架',price_review:'调价审核中'}
const filtered=computed(()=>store.products.filter(p=>p.name.includes(query.value.name)&&(!query.value.code||`${p.code||''} ${p.sku}`.toLowerCase().includes(query.value.code.toLowerCase()))&&(!query.value.park||p.parkIds.includes(query.value.park))))
const list=computed(()=>filtered.value.filter(p=>tab.value==='all'||p.status===tab.value))
const productTabs = [['all','全部'], ...Object.entries(labels)]
const count = (key:string) => filtered.value.filter(p=>key==='all'||p.status===key).length
const rows=computed(()=>list.value.slice((page.value-1)*8,page.value*8))
function search(){query.value={name:name.value.trim(),code:code.value.trim(),park:park.value};page.value=1}
function reset(){name.value='';code.value='';park.value='';tab.value='all';search()}
async function remove(id:string){try{await ElMessageBox.confirm('确定删除该商品？','删除商品',{type:'warning'});store.remove(id);ElMessage.success('已删除')}catch{}}
async function edit(p:Product){if(p.status==='on_sale'||p.status==='price_review'){try{await ElMessageBox.confirm('修改将先保存为草稿，提交后需审核，当前上架信息保持生效。是否继续？','编辑商品',{type:'warning',confirmButtonText:'继续编辑',cancelButtonText:'取消'})}catch{return}}router.push('/product/edit/'+p.id)}
function openAdjust(p:Product,kind:'stock'|'price'|'history'|'audit',historyParkId=''){if(kind==='audit'){if(route.name==='product')saveListState();router.push({name:'product-approvals',params:{id:p.id},query:route.name==='product-detail'?{returnTo:route.fullPath}:{from:'list'}});return}if(kind==='price' && (p.pendingEdit || p.pendingPrice || p.parkIds.some(id=>parkState(p,id)==='reviewing'))){ElMessage.warning('存在待审核事项，请先完成审核');return}target.value=p;priceNote.value='';priceHistoryPark.value='';priceExpandedPark.value='';priceOwner.value=ob.activeId;priceTargets.value=p.parkIds.filter(id=>c.joinedParks.some(park=>park.id===id)&&parkState(p,id)==='on_sale');Object.assign(priceDefaults,p.supply);for(const k of Object.keys(priceDrafts))delete priceDrafts[k];for(const id of p.parkIds)priceDrafts[id]={...(p.parks[id]||p.supply)};priceFields.value=[];if(kind==='stock'){initialiseStock(p);stockOpen.value=true};if(kind==='price')priceOpen.value=true;if(kind==='history'){historyPark.value=historyParkId;historyMode.value='taxed';historyExample.value=false;historyOpen.value=true}}
function adjust(){const p=target.value;if(!p)return;if(stockOpen.value){const current=store.products.find(item=>item.id===p.id), changed=changedStockIds.value;if(!changed.length){ElMessage.warning('请先修改库存');return}if(stockOwner.value!==ob.activeId||!current||current.status==='draft'||changed.some(id=>!c.joinedParks.some(park=>park.id===id)||!eligiblePark(current,id,'offline'))){ElMessage.warning('商品或园区状态已变更，请重新打开库存管理');return}if(changed.some(id=>!Number.isSafeInteger(stockDraft[id])||Number(stockDraft[id])<0)){ElMessage.warning('库存须为大于或等于 0 的整数');return}const conflict=changed.find(id=>current.parks[id].stock!==stockOriginal[id]);if(conflict){ElMessage.warning(`${parkName(conflict)}的库存已变化，请重新打开后修改`);return}const updated=JSON.parse(JSON.stringify(current)) as Product;for(const id of changed)updated.parks[id].stock=stockDraft[id]!;store.save(updated);stockOpen.value=false;ElMessage.success(`已更新 ${changed.length} 个园区的库存`)}else{if(!priceTargets.value.length){ElMessage.warning('请选择调价园区');return}const current=store.products.find(item=>item.id===p.id);if(priceOwner.value!==ob.activeId||!current||current.status==='draft'||hasReview(current)||current.status==='price_review'||priceTargets.value.some(id=>!c.joinedParks.some(park=>park.id===id)||!eligiblePark(current,id,'offline'))){ElMessage.warning('商品或园区状态已变更，请重新打开调价');return}if(priceTargets.value.some(id=>!priceDrafts[id]||!validSupplyPrice(priceDrafts[id]))){ElMessage.warning('请检查各园区的税点、价格和优惠方案');return}const taxChanged=priceTargets.value.some(id=>priceDrafts[id].tax!==current.parks[id]?.tax);if(taxChanged && (current.parkIds.some(id=>!priceTargets.value.includes(id)) || current.parkIds.some(id=>priceDrafts[id]?.tax!==priceDefaults.tax))){ElMessage.warning('税点调整须覆盖全部发布园区并保持一致，请重新同步');return}current.pendingPrice={parkIds:[...priceTargets.value],values:Object.fromEntries(priceTargets.value.map(id=>[id,{...priceDrafts[id]}])),note:priceNote.value};current.approvalLog=submitApprovals(current,'调价审批',c.joinedParks.filter(park=>priceTargets.value.includes(park.id)),priceNote.value);current.status='price_review';store.save(current);priceOpen.value=false;ElMessage.success('调价已提交审核')}}
function syncPrices(){if(!priceFields.value.length||!priceTargets.value.length){ElMessage.warning('请选择同步字段和目标园区');return}if(priceFields.value.includes('tax') && target.value?.parkIds.some(id=>!priceTargets.value.includes(id))){ElMessage.warning('税点须同步至全部发布园区；如有园区无法选择，请前往编辑商品统一调整');return}for(const id of priceTargets.value){const target=priceDrafts[id];if(!target)continue;for(const field of priceFields.value){if(field==='promotion'){target.promotion=priceDefaults.promotion;target.discount=priceDefaults.discount;target.fixed=priceDefaults.fixed}else if(['tax','cost','original'].includes(field)){const k=field as 'tax'|'cost'|'original';target[k]=priceDefaults[k]}}}ElMessage.success('已同步所选价格字段')}
function parkState(p:Product,id:string) { return p.parkStatuses?.[id] ?? (p.status === 'on_sale' || p.status === 'price_review' ? 'on_sale' : p.status === 'reviewing' ? 'reviewing' : p.status === 'rejected' ? 'rejected' : 'offline') }
function parkListings(p:Product) { return Object.fromEntries(p.parkIds.filter(()=>p.status!=='draft').map(id=>[id,{status:parkState(p,id),reason:p.parkRejectionReasons?.[id]}])) }
function aggregate(p:Product) { const states=p.parkIds.map(id=>parkState(p,id)); return states.includes('on_sale')?'on_sale':states.includes('reviewing')?'reviewing':states.includes('rejected')?'rejected':'offline' }
function hasReview(p:Product) { return !!p.pendingEdit || !!p.pendingPrice || p.parkIds.some(id=>parkState(p,id)==='reviewing') }
function review(p:Product,result:'approved'|'rejected'){
  const approvalType=p.pendingEdit?'商品资料变更':p.pendingPrice?'调价审批':'上架审批'
  const approvalParks=p.pendingEdit?undefined:p.pendingPrice?[...p.pendingPrice.parkIds]:p.parkIds.filter(id=>parkState(p,id)==='reviewing')
  if(p.pendingEdit){
    if(result==='approved') { const change=p.pendingEdit; for(const id of p.parkIds){const supply=p.parks[id], next=change.parks[id];if(supply && next && supply.tax!==next.tax){p.priceHistory=[...(p.priceHistory||[]),{time:new Date().toLocaleString('zh-CN'),parkId:id,original:supply.original,sale:salePrice(supply),tax:supply.tax}];supply.tax=next.tax}}p.supply.tax=change.supply.tax;Object.assign(p,{name:change.name,category:change.category,brand:change.brand,sku:change.sku,unit:change.unit,salesArea:change.salesArea,model:change.model,spec:change.spec,taxCode:change.taxCode,contractName:change.contractName,features:change.features,freightMode:change.freightMode,attrs:change.attrs,description:change.description,cover:change.cover,images:change.images});p.editDraft=undefined }
    p.pendingEdit=undefined
  }else if(p.pendingPrice){
    if(result==='approved' && p.parkIds.every(id=>p.pendingPrice!.parkIds.includes(id)) && p.parkIds.every(id=>p.pendingPrice!.values[id]?.tax===p.pendingPrice!.values[p.parkIds[0]]?.tax) && p.parkIds.some(id=>p.parks[id]?.tax!==p.pendingPrice!.values[id]?.tax))p.supply.tax=p.pendingPrice.values[p.parkIds[0]].tax
    if(result==='approved')for(const id of p.pendingPrice.parkIds){const supply=p.parks[id];if(!supply)continue;p.priceHistory=[...(p.priceHistory||[]),{time:new Date().toLocaleString('zh-CN'),parkId:id,original:supply.original,sale:salePrice(supply),tax:supply.tax}];const next=p.pendingPrice.values[id];if(next){supply.tax=next.tax;supply.cost=next.cost;supply.original=next.original;supply.promotion=next.promotion;supply.discount=next.discount;supply.fixed=next.fixed}}
    p.pendingPrice=undefined
  }else{
    p.parkStatuses={...p.parkStatuses};p.parkRejectionReasons={...p.parkRejectionReasons};for(const id of p.parkIds)if(parkState(p,id)==='reviewing'){p.parkStatuses[id]=result==='approved'?'on_sale':'rejected';if(result==='approved')delete p.parkRejectionReasons[id];else p.parkRejectionReasons[id]='演示审核未通过，请核对商品资料后重新提交。'}
  }
  p.status=aggregate(p);p.approvalLog=finishApprovals(p,approvalType,result,approvalParks);store.save(p);ElMessage.success('演示审核结果已更新')
}
function eligiblePark(p:Product,id:string,action:'on_sale'|'offline'){if(!p.parkIds.includes(id)||!p.parks[id])return false;const state=parkState(p,id);return action==='on_sale' ? state==='offline'||state==='rejected' : state==='on_sale'}
function parkLabel(p:Product,id:string){if(!p.parkIds.includes(id))return '未发布';return {on_sale:'已上架',offline:'已下架',reviewing:'审核中',rejected:'上架驳回'}[parkState(p,id)]}
const selectableParks=computed(()=>target.value?c.joinedParks.filter(park=>eligiblePark(target.value!,park.id,parkAction.value)):[])
function selectAllParks(){parkTargets.value=selectableParks.value.map(park=>park.id)}
function openPark(p:Product,action:'on_sale'|'offline'){if(p.pendingEdit||p.pendingPrice){ElMessage.warning('存在待审核事项，请先完成审核');return}target.value=p;parkTargets.value=[];parkAction.value=action;parkOpen.value=true}
function applyPark(){if(!target.value||!parkTargets.value.length){ElMessage.warning('请选择园区');return}const p=store.products.find(item=>item.id===target.value?.id);if(!p||p.status==='draft'||p.pendingEdit||p.pendingPrice||parkTargets.value.some(id=>!eligiblePark(p,id,parkAction.value))){ElMessage.warning('商品或园区状态已变更，请重新选择');return}p.parkStatuses=Object.fromEntries(p.parkIds.map(id=>[id,parkState(p,id)]));for(const id of parkTargets.value)p.parkStatuses[id]=parkAction.value==='on_sale'?'reviewing':'offline';p.status=aggregate(p);if(parkAction.value==='on_sale')p.approvalLog=submitApprovals(p,'上架审批',c.joinedParks.filter(park=>parkTargets.value.includes(park.id))); store.save(p);parkOpen.value=false;ElMessage.success(parkAction.value==='on_sale'?'已提交上架审核':'所选园区已下架')}

function openOrders(p:Product){const origin=route.name==='product-detail'?'detail':'list';if(origin==='list')saveListState();const backOrder=typeof route.query.fromOrder==='string'?route.query.fromOrder:'';const backReturn=typeof route.query.orderReturn==='string'?route.query.orderReturn:'';router.push({path:'/procurement/orders',query:{productId:p.id,fromProduct:p.id,origin,...(backOrder?{backOrder}:{}),...(backReturn?{backReturn}:{})}})}
function menuAction(p:Product,command:string){
  if(command==='edit')edit(p)
  else if(command==='offline')openPark(p,'offline')
  else if(command==='stock')openAdjust(p,'stock')
  else if(command==='price')openAdjust(p,'price')
  else if(command==='audit')openAdjust(p,'audit')
  else if(command==='orders')openOrders(p)
  else if(command==='history')openAdjust(p,'history')
  else if(command==='approve')review(p,'approved')
  else if(command==='reject')review(p,'rejected')
  else if(command==='delete')remove(p.id)
}
function displayParkIds(p:Product) { return p.status==='draft' ? [] : p.parkIds.filter(id=>!!p.parks[id]) }
function shownParkIds(p:Product) { const ids=displayParkIds(p); return query.value.park ? ids.filter(id=>id===query.value.park) : ids }
function parkName(id:string) { return c.joinedParks.find(park=>park.id===id)?.name || id }
function priceWithTax(s:Supply) { return salePrice(s)*(1+s.tax/100) }
function priceRange(p:Product) { const prices=shownParkIds(p).map(id=>priceWithTax(p.parks[id])).filter(Number.isFinite); if(!prices.length)return '—'; const low=Math.min(...prices),high=Math.max(...prices); return `¥${low.toFixed(2)}${high===low?'':`–${high.toFixed(2)}`}` }
function displayTone(p:Product) { if(p.status==='draft')return 'draft'; if(query.value.park && p.parkIds.includes(query.value.park))return parkState(p,query.value.park); return p.status==='price_review' ? aggregate(p) : p.status }
function displayStatus(p:Product) { return {draft:'草稿',on_sale:'已上架',offline:'已下架',reviewing:'审核中',rejected:'已驳回'}[displayTone(p)] }
function rejectedPark(p:Product) { return shownParkIds(p).find(id=>parkState(p,id)==='rejected') }
function tableStock(p:Product) { const ids=shownParkIds(p); if(!ids.length)return '发布后设置园区价格'; if(query.value.park)return `库存 ${p.parks[ids[0]].stock} ${p.unit||'件'}`; return `${ids.length} 个园区 · 展开查看库存` }
function canDetailPark(p:Product, action:'on_sale'|'offline') { return p.status!=='draft' && !p.pendingEdit && !p.pendingPrice && p.parkIds.some(id=>eligiblePark(p,id,action)) }
function toggleProduct(id:string) { expandedProduct.value=expandedProduct.value===id?null:id }
function fill(){store.fillSamples();page.value=1;ElMessage.success('演示商品已添入')}
</script>
<template><div class="biz-page product-page"><template v-if="route.name!=='product-detail'"><header class="biz-head product-head"><div class="heading"><span class="icon"><Package :size="24"/></span><h1>商品管理</h1></div><div class="head-actions"><ElButton @click="fill">演示填入</ElButton><ElButton type="primary" @click="router.push('/product/new')"><Plus :size="15"/>发布商品</ElButton></div></header>
<div class="product-workspace"><div class="product-sticky list-sticky"><ListFilterBar><ElSelect v-model="park" clearable placeholder="全部已加入园区"><ElOption v-for="p in c.joinedParks" :key="p.id" :label="p.name" :value="p.id"/></ElSelect><ElInput v-model="name" placeholder="搜索商品名称" clearable @keyup.enter="search"><template #prefix><Search :size="15"/></template></ElInput><ElInput v-model="code" placeholder="商品编码 / 供应商 SKU" clearable @keyup.enter="search"/><template #actions><ElButton type="primary" @click="search">查询</ElButton><ElButton @click="reset">重置</ElButton></template></ListFilterBar>
<ListStatusTabs :model-value="tab" :items="productTabs" :count="count" @update:model-value="tab=$event;page=1"><template #actions><div class="view-switch" aria-label="显示方式"><ElButton :type="viewMode==='list'?'primary':'default'" :plain="viewMode!=='list'" aria-label="列表视图" @click="viewMode='list'"><List :size="16"/></ElButton><ElButton :type="viewMode==='grid'?'primary':'default'" :plain="viewMode!=='grid'" aria-label="宫格视图" @click="viewMode='grid'"><LayoutGrid :size="16"/></ElButton><ElButton :type="viewMode==='table'?'primary':'default'" :plain="viewMode!=='table'" aria-label="表格视图" title="表格视图" @click="viewMode='table'"><TableProperties :size="16"/></ElButton></div></template></ListStatusTabs></div>
<div v-if="!rows.length" class="biz-empty"><h3>暂无符合条件的商品</h3><p>可调整筛选条件，或发布新的商品。</p><ElButton @click="reset">清空筛选</ElButton><ElButton type="primary" @click="router.push('/product/new')">发布商品</ElButton></div>
<div v-else-if="viewMode==='table'" class="product-table">
  <div class="product-table-head product-table-columns"><span>商品信息</span><span>{{query.park?'所选园区状态':'整体状态 / 待处理'}}</span><span>园区价格 / 库存</span><span>最近更新</span><span class="table-action-heading">操作</span></div>
  <article v-for="p in rows" :key="p.id" class="table-product">
    <div class="product-table-row product-table-columns">
      <div class="table-identity"><button class="table-cover" :aria-label="`查看${p.name||'商品'}详情`" @click="showDetail(p)"><DemoImage :source="p.cover" empty-text="暂无图片"/></button><div class="table-identity-text"><button class="table-name" :title="p.name" @click="showDetail(p)">{{p.name||'未命名商品'}}</button><div class="table-secondary">{{p.code||'待生成'}} <span class="table-separator">｜</span> {{p.category||'未选择类目'}}</div></div></div>
      <div class="table-state"><div class="table-state-label" :class="`tone-${displayTone(p)}`"><i class="state-dot" :class="`state-${displayTone(p)}`"></i>{{displayStatus(p)}}</div><div v-if="rejectedPark(p)" class="table-secondary table-rejection">{{parkName(rejectedPark(p)!)}}：已驳回</div><div v-else-if="p.pendingPrice || p.status==='price_review'" class="table-secondary">调价审核中，当前价格仍生效</div><div v-else-if="p.pendingEdit" class="table-secondary">资料修改审核中</div><button v-if="displayParkIds(p).length" class="table-expand" :aria-expanded="expandedProduct===p.id" @click="toggleProduct(p.id)">{{expandedProduct===p.id?'收起':'查看'}}园区详情<ChevronDown :size="14" :stroke-width="1.8" :class="{rotated:expandedProduct===p.id}"/></button></div>
      <div><strong class="table-price" title="含税销售价">{{priceRange(p)}}</strong><div class="table-secondary">{{tableStock(p)}}</div></div>
      <div class="table-date">{{p.updatedAt?.slice(0,10)||'—'}}<div class="table-secondary">销量 {{p.sales||0}}</div></div>
      <div class="table-actions">
        <ElButton text @click="showDetail(p)">详情</ElButton><ElButton text :disabled="p.status==='draft'||!p.parkIds.some(id=>eligiblePark(p,id,'on_sale'))||!!p.pendingEdit||!!p.pendingPrice" @click="openPark(p,'on_sale')">上架</ElButton><ElButton text :disabled="p.status==='draft'||!p.parkIds.some(id=>parkState(p,id)==='on_sale')||hasReview(p)||p.status==='price_review'" @click="openAdjust(p,'price')">调价</ElButton>
        <ElButton text :disabled="p.status==='draft'||!p.parkIds.some(id=>parkState(p,id)==='on_sale')" @click="openAdjust(p,'stock')">改库存</ElButton><ElButton text @click="openAdjust(p,'audit')">审批记录</ElButton><ElDropdown trigger="click" @command="menuAction(p,$event)"><ElButton text class="table-more-button" aria-label="更多商品操作">更多<ChevronDown :size="14" :stroke-width="1.8"/></ElButton><template #dropdown><ElDropdownMenu><ElDropdownItem command="edit">编辑</ElDropdownItem><ElDropdownItem v-if="p.status!=='draft' && p.parkIds.some(id=>eligiblePark(p,id,'offline'))" command="offline">下架</ElDropdownItem><ElDropdownItem command="history">历史价格</ElDropdownItem><ElDropdownItem command="orders">订单记录</ElDropdownItem><ElDropdownItem v-if="hasReview(p)" command="approve">演示审核通过</ElDropdownItem><ElDropdownItem v-if="hasReview(p)" command="reject">演示审核驳回</ElDropdownItem><ElDropdownItem command="delete" :disabled="p.status!=='draft'&&p.status!=='offline'" divided>删除商品</ElDropdownItem></ElDropdownMenu></template></ElDropdown>
      </div>
    </div>
    <div v-if="expandedProduct===p.id" class="table-park-details"><div class="table-details-title">全部已发布园区 · 含税销售价与库存</div><div v-for="id in displayParkIds(p)" :key="id" class="table-park-line"><strong>{{parkName(id)}}</strong><span>{{parkLabel(p,id)}}</span><span>¥{{priceWithTax(p.parks[id]).toFixed(2)}} / {{p.unit||'件'}} · 库存 {{p.parks[id].stock}}</span><span class="table-rejection">{{parkState(p,id)==='rejected' ? (p.parkRejectionReasons?.[id]||'未记录驳回意见，请联系园区核实。') : ''}}</span></div></div>
  </article>
</div>
<div v-else class="biz-list" :class="{'product-grid':viewMode==='grid'}">
  <article v-for="p in rows" :key="p.id" class="product-row">
    <button class="cover" :aria-label="`查看${p.name||'商品'}详情`" @click="showDetail(p)"><DemoImage :source="p.cover" empty-text="暂无图片" /></button>
    <div class="body">
      <div class="title"><button :title="p.name" @click="showDetail(p)">{{p.name||'未命名商品'}}</button><ElTag size="small" :type="p.status==='on_sale'?'success':p.status==='rejected'?'danger':p.status==='reviewing'||p.status==='price_review'?'warning':'info'">{{labels[p.status]}}</ElTag><ElTag v-if="p.pendingEdit" size="small" type="warning">资料修改审核中</ElTag></div>
      <ParkListingStatuses :parks="c.joinedParks" :listings="parkListings(p)" rejection-fallback="请核对商品资料并重新提交。"/>
      <p class="product-price">含税销售价 <b>¥{{(salePrice(p.supply)*(1+p.supply.tax/100)).toFixed(2)}} / {{p.unit}}</b></p>
      <small class="product-meta"><span>更新 {{p.updatedAt.slice(0,10)}}</span><span>商品编码 {{p.code||'待生成'}}</span><span>供应商 SKU {{p.sku||'—'}}</span></small>
    </div>
    <div class="product-side"><div class="product-summary"><span :title="p.category">{{p.category||'未选择类目'}}</span><span>累计销量 <b>{{p.sales||0}}</b></span></div>
      <div class="actions">
        <ElButton text @click="showDetail(p)"><Eye :size="14"/>详情</ElButton>
        <ElButton v-if="p.status!=='draft' && p.parkIds.some(id=>eligiblePark(p,id,'on_sale'))" text type="primary" @click="openPark(p,'on_sale')"><ArrowUpToLine :size="14"/>上架</ElButton>
        <ElButton v-if="p.status!=='draft' && p.parkIds.some(id=>parkState(p,id)==='on_sale')" text :disabled="hasReview(p)" @click="openAdjust(p,'price')"><Coins :size="14"/>调价</ElButton>
        <ElButton v-if="p.status!=='draft' && p.parkIds.some(id=>parkState(p,id)==='on_sale')" text @click="openAdjust(p,'stock')"><PackageCheck :size="14"/>改库存</ElButton>
        <ElButton text @click="openAdjust(p,'audit')"><ClipboardList :size="14"/>审批记录</ElButton>
        <ElDropdown trigger="click" @command="menuAction(p,$event)"><ElButton text aria-label="更多商品操作"><MoreHorizontal :size="18"/>更多</ElButton><template #dropdown><ElDropdownMenu>
          <ElDropdownItem command="edit"><Pencil :size="14"/>编辑</ElDropdownItem><ElDropdownItem v-if="p.status!=='draft' && p.parkIds.some(id=>eligiblePark(p,id,'offline'))" command="offline">下架</ElDropdownItem><ElDropdownItem command="history">历史价格</ElDropdownItem><ElDropdownItem command="orders">订单记录</ElDropdownItem><ElDropdownItem v-if="hasReview(p)" command="approve">演示审核通过</ElDropdownItem><ElDropdownItem v-if="hasReview(p)" command="reject">演示审核驳回</ElDropdownItem><ElDropdownItem command="delete" :disabled="p.status!=='draft'&&p.status!=='offline'" divided>删除商品</ElDropdownItem>
        </ElDropdownMenu></template></ElDropdown>
      </div>
    </div>
  </article>
</div><ListPagination v-model:page="page" :page-size="8" :total="list.length" noun="件商品"/></div>
</template>
<section v-else-if="currentProduct" class="product-detail-page">
  <SecondaryPageHeader title="商品详情" :back-label="route.query.fromOrder?'返回订单详情':'返回商品管理'" @back="backFromDetail"><div class="detail-page-actions"><ElButton :disabled="!canDetailPark(currentProduct,'on_sale')" @click="openPark(currentProduct,'on_sale')">上架</ElButton><ElButton :disabled="!canDetailPark(currentProduct,'offline')" @click="openPark(currentProduct,'offline')">下架</ElButton><ElButton type="primary" @click="edit(currentProduct)">编辑商品</ElButton></div></SecondaryPageHeader>
  <div class="detail-hero"><div class="detail-media"><div class="detail-main-image"><DemoMedia v-if="detailMedia" :source="detailMedia" fit="contain"/><DemoImage v-else empty-text="暂无商品图片"/></div><div class="detail-thumbnails"><button v-for="(image,i) in [currentProduct.cover,...currentProduct.images].filter(Boolean)" :key="i" :class="{selected:detailMedia===image}" :aria-label="`查看商品媒体 ${i+1}`" @click="detailMedia=image"><DemoMedia :source="image" fit="contain"/></button></div></div>
    <div class="detail-overview"><div class="detail-name-line"><h2>{{currentProduct.name||'未命名商品'}}</h2><ElTag size="small" :type="currentProduct.status==='on_sale'?'success':currentProduct.status==='rejected'?'danger':currentProduct.status==='reviewing'||currentProduct.status==='price_review'?'warning':'info'">{{labels[currentProduct.status]}}</ElTag></div>
      <div class="detail-hero-park" v-if="currentProduct.parkIds.length"><label for="detail-hero-park">查看园区</label><select id="detail-hero-park" v-model="detailPark"><option v-for="id in currentProduct.parkIds" :key="id" :value="id">{{parkName(id)}}</option></select></div>
      <div class="detail-price-block"><template v-if="detailPark && currentProduct.parks[detailPark]"><span>销售价（含税）</span><strong>¥{{priceWithTax(currentProduct.parks[detailPark]).toFixed(2)}}</strong><del>¥{{(currentProduct.parks[detailPark].original*(1+currentProduct.parks[detailPark].tax/100)).toFixed(2)}}</del><span> / {{currentProduct.unit||'件'}}</span><p>未税销售价 ¥{{salePrice(currentProduct.parks[detailPark]).toFixed(2)}}　（税率 {{currentProduct.parks[detailPark].tax}}%）</p></template><template v-else><span>销售价</span><strong>—</strong><p>暂无园区供货与价格配置</p></template></div>
      <dl class="detail-overview-grid"><div><dt>品牌名称</dt><dd>{{currentProduct.brand||'—'}}</dd></div><div><dt>商品型号</dt><dd>{{currentProduct.model||'—'}}</dd></div><div><dt>规格</dt><dd>{{currentProduct.spec||'—'}}</dd></div><div><dt>订货编码</dt><dd>{{currentProduct.sku||'—'}} <button v-if="currentProduct.sku" class="detail-copy-button" @click="copySku(currentProduct.sku)">复制</button></dd></div><div><dt>起订量</dt><dd>{{detailPark && currentProduct.parks[detailPark] ? `${currentProduct.parks[detailPark].minimum} ${currentProduct.unit||'件'}` : '—'}}</dd></div><div><dt>销售单位</dt><dd>{{currentProduct.unit||'—'}}</dd></div><div><dt>库存</dt><dd>{{detailPark && currentProduct.parks[detailPark] ? `${currentProduct.parks[detailPark].stock} ${currentProduct.unit||'件'}` : '—'}}</dd></div></dl></div></div>
  <div class="detail-content"><nav class="detail-tabs" aria-label="商品详情分类"><button :class="{active:detailTab==='basic'}" @click="detailTab='basic'">基本信息</button><button :class="{active:detailTab==='supply'}" @click="detailTab='supply'">供货与价格</button><button :class="{active:detailTab==='description'}" @click="detailTab='description'">图文详情</button></nav>
    <template v-if="detailTab==='basic'"><section class="detail-section"><h2>基础信息</h2><dl class="detail-fields"><div><dt>商品类目</dt><dd>{{currentProduct.category||'—'}}</dd></div><div><dt>商品标题</dt><dd>{{currentProduct.name||'—'}}</dd></div><div><dt>供应商 SKU</dt><dd>{{currentProduct.sku||'—'}}</dd></div><div><dt>商品品牌</dt><dd>{{currentProduct.brand||'—'}}</dd></div><div><dt>商品型号</dt><dd>{{currentProduct.model||'—'}}</dd></div><div><dt>规格</dt><dd>{{currentProduct.spec||'—'}}</dd></div><div><dt>计量单位</dt><dd>{{currentProduct.unit||'—'}}</dd></div><div><dt>税收分类编码</dt><dd>{{currentProduct.taxCode||'—'}}</dd></div><div><dt>商品合同名称</dt><dd>{{currentProduct.contractName||'—'}}</dd></div><div><dt>销售区域</dt><dd>{{currentProduct.salesArea||'不限制'}}</dd></div></dl></section><section class="detail-section"><h2>销售属性</h2><dl v-if="currentProduct.attrs?.some(a=>a.name&&a.value)" class="detail-fields"><div v-for="a in currentProduct.attrs.filter(a=>a.name&&a.value)" :key="a.id"><dt>{{a.name}}</dt><dd>{{a.value}}</dd></div></dl><p v-else class="detail-muted">暂无销售属性</p></section><section class="detail-section"><h2>物流信息</h2><dl class="detail-fields"><div><dt>运费模式</dt><dd>{{currentProduct.freightMode||'免运费'}}</dd></div></dl></section></template>
    <template v-else-if="detailTab==='supply'"><section class="detail-section detail-supply-area"><div class="detail-section-head"><div><h2>发布园区</h2><p class="detail-muted">选择园区查看对应的上架状态、供货与价格</p></div></div><div v-if="currentProduct.status==='draft'" class="detail-muted">草稿尚未发布园区，以下为已配置的供货信息。</div><div v-if="currentProduct.parkIds.length" class="detail-park-picker"><button v-for="id in currentProduct.parkIds" :key="id" :class="{active:detailPark===id}" @click="detailPark=id"><strong>{{parkName(id)}}</strong><span>{{currentProduct.status==='draft'?'草稿':parkLabel(currentProduct,id)}}</span></button></div><p v-else class="detail-muted">暂无配置园区</p><div v-if="detailPark" class="detail-park-panel"><div class="detail-park-panel-head"><div><h3>{{parkName(detailPark)}}</h3><span>{{currentProduct.status==='draft'?'草稿':parkLabel(currentProduct,detailPark)}}</span></div><ElButton @click="openAdjust(currentProduct,'history',detailPark)">查看历史价格</ElButton></div><template v-if="currentProduct.parks[detailPark]"><div class="detail-park-section"><h2>供货信息</h2><dl class="detail-fields detail-supply-fields"><div><dt>货期</dt><dd>{{currentProduct.parks[detailPark].leadDays}} 天</dd></div><div><dt>最小起售量</dt><dd>{{currentProduct.parks[detailPark].minimum}} {{currentProduct.unit}}</dd></div><div><dt>递增量</dt><dd>{{currentProduct.parks[detailPark].increment}} {{currentProduct.unit}}</dd></div><div><dt>库存</dt><dd>{{currentProduct.parks[detailPark].stock}} {{currentProduct.unit}}</dd></div></dl></div><div class="detail-park-section"><h2>价格信息</h2><p class="detail-muted">税点 {{currentProduct.parks[detailPark].tax}}%　·　优惠 {{currentProduct.parks[detailPark].promotion==='discount'?`折扣价 ${currentProduct.parks[detailPark].discount}%`:currentProduct.parks[detailPark].promotion==='fixed'?`固定价 ¥${Number(currentProduct.parks[detailPark].fixed).toFixed(2)}`:'无优惠'}}</p><table class="detail-price-table"><thead><tr><th></th><th>采购价</th><th>原价</th><th>销售价</th></tr></thead><tbody><tr><th>未税价</th><td>¥{{Number(currentProduct.parks[detailPark].cost).toFixed(2)}}</td><td>¥{{Number(currentProduct.parks[detailPark].original).toFixed(2)}}</td><td>¥{{salePrice(currentProduct.parks[detailPark]).toFixed(2)}}</td></tr><tr><th>含税价</th><td>¥{{(currentProduct.parks[detailPark].cost*(1+currentProduct.parks[detailPark].tax/100)).toFixed(2)}}</td><td>¥{{(currentProduct.parks[detailPark].original*(1+currentProduct.parks[detailPark].tax/100)).toFixed(2)}}</td><td>¥{{priceWithTax(currentProduct.parks[detailPark]).toFixed(2)}}</td></tr><tr><th>毛利</th><td>—</td><td>{{margin(currentProduct.parks[detailPark].original,currentProduct.parks[detailPark].cost)}}</td><td>{{margin(salePrice(currentProduct.parks[detailPark]),currentProduct.parks[detailPark].cost)}}</td></tr></tbody></table></div></template><p v-else class="detail-muted">该园区暂无供货配置。</p></div></section></template>
    <template v-else><section class="detail-section"><h2>产品特点</h2><p class="detail-copy">{{currentProduct.features||'暂无产品特点'}}</p></section><section class="detail-section"><h2>商品详情</h2><div class="rich-preview detail-copy" v-html="safeProductHtml(currentProduct.description)||'暂无商品详情'"></div></section></template>
  </div><div class="detail-page-footer"><ElButton @click="openAdjust(currentProduct,'audit')">审批记录</ElButton><ElButton @click="openOrders(currentProduct)">订单记录</ElButton></div>
</section><section v-else class="detail-missing"><h2>未找到该商品</h2><p>商品可能已删除或不属于当前供应商。</p><ElButton @click="router.push('/product')">返回商品管理</ElButton></section>
<ElDialog v-model="parkOpen" :title="parkAction==='on_sale'?'提交上架审核':'按园区下架'" width="min(600px, 90vw)" class="park-action-dialog">
  <p class="park-action-intro" v-if="parkAction==='on_sale'">选择需要上架的园区。已驳回或已下架的商品须重新提交审核，通过后上架。</p>
  <p class="park-action-intro" v-else>选择需要下架的园区，下架后该园区将不再展示此商品。</p>
  <ElCheckboxGroup v-model="parkTargets" class="park-action-list">
    <div v-for="p in c.joinedParks" :key="p.id" class="park-action-item" :class="{'is-rejected':target && target.parkIds.includes(p.id) && parkState(target,p.id)==='rejected'}">
      <div class="park-action-heading"><ElCheckbox :value="p.id" :disabled="!target || !eligiblePark(target,p.id,parkAction)">{{p.name}}</ElCheckbox><ElTag v-if="target" size="small" :type="!target.parkIds.includes(p.id)?'info':parkState(target,p.id)==='rejected'?'danger':parkState(target,p.id)==='on_sale'?'success':parkState(target,p.id)==='reviewing'?'warning':'info'">{{parkLabel(target,p.id)}}</ElTag></div>
      <div v-if="target && target.parkIds.includes(p.id) && parkState(target,p.id)==='rejected'" class="park-rejection"><strong>上架驳回意见</strong><p>{{target.parkRejectionReasons?.[p.id] || '未记录驳回意见，请联系园区核实。'}}</p></div>
      <p v-if="target && !target.parkIds.includes(p.id)" class="park-action-note">尚未配置此园区的供货信息。</p>
    </div>
  </ElCheckboxGroup>
  <template #footer><div class="park-action-footer"><ElButton :disabled="!selectableParks.length" @click="selectAllParks">全选可操作园区</ElButton><div><ElButton @click="parkOpen=false">取消</ElButton><ElButton type="primary" :disabled="!parkTargets.length" @click="applyPark">{{parkAction==='on_sale'?'提交上架审核':'确认下架'}}</ElButton></div></div></template>
</ElDialog><ElDialog v-model="stockOpen" title="按园区修改库存" width="min(760px, 90vw)" class="stock-dialog"><p class="stock-intro">可同时修改多个已上架园区；保存后立即生效。</p><div v-if="stockIds.length" class="stock-batch"><div><strong>批量设置</strong><span>勾选园区后可统一填入库存，也可逐行修改。</span></div><div class="stock-batch-controls"><ElInputNumber v-model="stockBatch" :min="0" :precision="0" placeholder="统一库存" aria-label="统一库存"/><ElButton :disabled="!stockSelected.length" @click="applyStockBatch">应用到已选 {{stockSelected.length}} 个园区</ElButton></div></div><div v-if="stockIds.length" class="stock-table-wrap"><table class="stock-table"><thead><tr><th><ElCheckbox :model-value="stockSelected.length===stockIds.length" :indeterminate="stockSelected.length>0&&stockSelected.length<stockIds.length" aria-label="选择全部园区" @change="stockSelected=$event ? [...stockIds] : []"/></th><th>已上架园区</th><th>当前库存</th><th>新库存</th></tr></thead><tbody><tr v-for="id in stockIds" :key="id"><td><ElCheckbox :model-value="stockSelected.includes(id)" :aria-label="`选择${parkName(id)}`" @change="selectStockPark(id,$event)"/></td><td><strong>{{parkName(id)}}</strong><span v-if="changedStockIds.includes(id)" class="stock-changed">已修改</span></td><td>{{stockOriginal[id]}} {{target?.unit||'件'}}</td><td><ElInputNumber v-model="stockDraft[id]" :min="0" :precision="0" :aria-label="`${parkName(id)}的新库存`"/> <span class="stock-unit">{{target?.unit||'件'}}</span></td></tr></tbody></table></div><div v-else class="stock-empty">暂无可修改库存的已上架园区。</div><template #footer><div class="stock-footer"><span>{{changedStockIds.length ? `已修改 ${changedStockIds.length} 个园区` : '修改的园区将在保存后生效'}}</span><div><ElButton @click="stockOpen=false">取消</ElButton><ElButton type="primary" :disabled="!changedStockIds.length" @click="adjust">保存修改</ElButton></div></div></template></ElDialog>
<ElDialog v-model="priceOpen" :title="priceHistoryPark ? '调价 · 历史价格' : '按园区提交调价审核'" width="min(960px, 90vw)" class="price-dialog" @closed="priceHistoryPark=''"><div ref="priceFormRef" v-show="!priceHistoryPark"><p>选择目标园区并分别调整价格。批量操作仅覆盖所选字段；税点须同步至全部发布园区，审核通过后生效。</p><ElCheckboxGroup v-model="priceTargets"><ElCheckbox v-for="p in c.joinedParks.filter(p=>target?.parkIds.includes(p.id))" :key="p.id" :value="p.id" :disabled="!target || parkState(target,p.id)!=='on_sale'">{{p.name}}</ElCheckbox></ElCheckboxGroup><div class="price-section"><h3>批量设置价格</h3><SupplyFields :key="`bulk-${priceFieldsRenderKey}`" :value="priceDefaults" price-only/><p>选择要同步的价格字段</p><ElCheckboxGroup v-model="priceFields"><ElCheckbox value="tax">税点</ElCheckbox><ElCheckbox value="cost">采购价</ElCheckbox><ElCheckbox value="original">原价</ElCheckbox><ElCheckbox value="promotion">优惠方案</ElCheckbox></ElCheckboxGroup><ElButton @click="syncPrices">同步所选字段</ElButton></div><div v-for="p in c.joinedParks.filter(p=>priceTargets.includes(p.id))" :key="p.id" class="park-price"><div class="price-park-head"><button type="button" class="price-park-toggle" :aria-expanded="priceExpandedPark===p.id" @click="priceExpandedPark=priceExpandedPark===p.id?'':p.id"><strong>{{p.name}}</strong><span>{{priceExpandedPark===p.id?'收起':'展开单独调整'}} <ChevronDown :size="14" :class="{'is-expanded':priceExpandedPark===p.id}"/></span></button><ElButton text type="primary" :aria-label="`查看${p.name}的历史价格`" @click="showPriceHistory(p.id)">查看历史价格</ElButton></div><template v-if="priceExpandedPark===p.id"><p>当前：税点 {{target?.parks[p.id]?.tax}}% · 原价 ¥{{Number(target?.parks[p.id]?.original||0).toFixed(2)}} · 销售价 ¥{{salePrice(target?.parks[p.id]||priceDefaults).toFixed(2)}}</p><SupplyFields v-if="priceDrafts[p.id]" :key="`${p.id}-${priceFieldsRenderKey}`" :value="priceDrafts[p.id]" price-only tax-locked/></template></div><p>提交说明（选填）</p><ElInput v-model="priceNote"/></div><ProductAdjustmentHistory v-if="priceHistoryPark" :park-name="parkName(priceHistoryPark)" :records="(target?.priceHistory||[]).filter(h=>h.parkId===priceHistoryPark)" @back="returnToPrice"/><template #footer><div v-if="!priceHistoryPark"><ElButton @click="priceOpen=false">取消</ElButton><ElButton type="primary" @click="adjust">提交审核</ElButton></div></template></ElDialog>
<ElDialog v-model="historyOpen" title="历史价格" width="min(900px, 90vw)" class="history-dialog"><div class="history-toolbar"><label>园区 <ElSelect v-model="historyPark" placeholder="全部园区" style="width:280px"><ElOption label="全部园区" value=""/><ElOption v-for="id in target ? historyParkIds(target) : []" :key="id" :value="id" :label="parkName(id)"/></ElSelect></label><div class="history-controls"><ElButton v-if="!historyExample" @click="showHistoryExample">查看图表示例</ElButton><ElButton v-else @click="historyExample=false">返回实际记录</ElButton></div></div><p v-if="historyExample" class="history-example">示例数据，仅用于展示图表，不会写入商品历史。</p><p v-else class="history-note">记录价格被替换时的价格；旧记录若未保存历史税率，含税价格显示为“—”。</p><div class="history-mode"><span>价格口径</span><button :class="{active:historyMode==='taxed'}" @click="historyMode='taxed'">含税</button><button :class="{active:historyMode==='untaxed'}" @click="historyMode='untaxed'">未税</button></div><ProductPriceHistoryChart v-if="historyPark || historyExample" :records="historyRows" :mode="historyMode"/><div v-else class="history-empty">选择园区后查看历史价格曲线。</div><table v-if="historyRows.length" class="detail-price-table history-table"><thead><tr><th>替换时间</th><th v-if="!historyPark && !historyExample">园区</th><th>{{historyMode==='taxed'?'含税原价':'未税原价'}}</th><th>{{historyMode==='taxed'?'含税销售价':'未税销售价'}}</th></tr></thead><tbody><tr v-for="(h,i) in historyRows" :key="i"><td>{{h.time}}</td><td v-if="!historyPark && !historyExample">{{parkName(h.parkId)}}</td><td>{{historyMode==='taxed'?historyTaxPrice(h.original,h.tax):`¥${Number(h.original).toFixed(2)}`}}</td><td>{{historyMode==='taxed'?historyTaxPrice(h.sale,h.tax):`¥${Number(h.sale).toFixed(2)}`}}</td></tr></tbody></table><div v-else-if="!historyPark && !historyExample" class="history-empty">暂无历史价格记录</div><template #footer><ElButton @click="historyOpen=false">关闭</ElButton></template></ElDialog>

</div></template>
